 public static String durText(long mins,String code){long h=mins/60,m=mins%60;if(code.startsWith("ar")){String hp=h==1?"ساعة":h==2?"ساعتان":h>=3&&h<=10?h+" ساعات":h+" ساعة";String mp=m==1?"دقيقة":m==2?"دقيقتان":m>=3&&m<=10?m+" دقائق":m+" دقيقة";if(h>0&&m>0)return hp+" و "+mp;if(h>0)return hp;if(m>0)return mp;return "أقل من دقيقة";}if(code.startsWith("en")){if(h>0&&m>0)return h+"h "+m+"m";if(h>0)return h+(h==1?" hour":" hours");if(m>0)return m+(m==1?" minute":" minutes");return "<1 min";}String hu,mu;if(code.startsWith("de")){hu="Std.";mu="Min.";}else if(code.startsWith("tr")){hu="sa";mu="dk";}else if(code.startsWith("id")){hu="jam";mu="mnt";}else if(code.startsWith("ru")){hu="ч";mu="мин";}else if(code.startsWith("ur")){hu="گھنٹے";mu="منٹ";}else{hu="h";mu="min";}if(h>0&&m>0)return h+" "+hu+" "+m+" "+mu;if(h>0)return h+" "+hu;if(m>0)return m+" "+mu;return "<1 "+mu;}
